import csv, glob
LOG = {}
for f in sorted(glob.glob('.github/downloader/logs/*.tsv')):
    for r in csv.reader(open(f, encoding='utf-8'), delimiter='\t'):
        if len(r) >= 5 and r[4] == 'ok': LOG[r[3]] = r[2]
def sha(p):
    h = hashlib.sha256(); h.update(open(p, 'rb').read()); return h.hexdigest()
for it in ITEMS: assert len((it[2] + '.html').encode()) <= 225, (it[2], len((it[2] + '.html').encode()))
new = []
for key, folder, name, short, pos in ITEMS:
    src = W + key + '.pdf'; hs = W + H + key + '.html'
    if os.path.exists(A + folder + name + '.pdf') or not os.path.exists(src): continue
    page = open(hs, encoding='utf-8', errors='replace').read()
    assert 'Документ утратил силу или отменен' not in re.sub(r'<[^>]+>', ' ', page[:200000]), key
    title = ' '.join(html.unescape(re.search(r'<title>(.*?)</title>', page, re.S).group(1)).split(' \\ ')[0].split())
    url = LOG.get(src, '')
    assert url, key
    os.makedirs(A + folder + H, exist_ok=True)
    shutil.copyfile(src, A + folder + name + '.pdf'); shutil.copyfile(hs, A + folder + H + name + '.html')
    new.append(dict(key=key, folder=folder, name=name, short=short, pos=pos, title=title, url=url))
print('размещено:', len(new), [n['key'] for n in new])
if new:
    npl = sum(1 for n in new if n['folder'] == PL); nob = len(new) - npl
    # --- реестр
    rp = A + 'Реестр источников.md'; s = open(rp, encoding='utf-8').read()
    rows = ['| %s | %s.pdf | [consultant.ru](%s) | %s |' % (n['folder'].split('/')[1], n['name'], n['url'], n['title'].replace('|', '/')) for n in new]
    head = '### А.11. Добавлено 16.11.2026 (последний добор): судебная практика\n\n'
    if head not in s:
        block = (head + 'Постановления Пленума и обзоры Верховного Суда РФ, которые раньше значились в разделе 2.2 как не скачанные, и два постановления Пленума 2024 года, '
                 'найденные при просмотре перечня постановлений за 2023–2026 годы. Тексты — consultant.ru (не официальный источник); редакция — по заголовку документа на сайте; '
                 'на каждой сохранённой странице проверено, что отметки «Документ утратил силу или отменен» нет.\n\n| Папка | Файл | Откуда | Что в файле |\n|---|---|---|---|\n')
        s = s.replace('## Б. Перепроверка 14.11.2026', block + '\n'.join(rows) + '\n\n## Б. Перепроверка 14.11.2026', 1)
    else:
        i = s.find(head); j = s.find('\n\n## Б. Перепроверка', i); s = s[:j] + '\n' + '\n'.join(rows) + s[j:]
    open(rp, 'w', encoding='utf-8').write(s)
    # --- контрольные суммы
    cp = A + 'Контрольные суммы SHA-256.txt'
    L = [l for l in open(cp, encoding='utf-8').read().split('\n') if l]
    for n in new:
        for rel in (n['folder'] + n['name'] + '.pdf', n['folder'] + H + n['name'] + '.html'): L.append('%s  %s' % (sha(A + rel), rel))
    L.sort(key=lambda l: l.split('  ', 1)[1])
    open(cp, 'w', encoding='utf-8').write('\n'.join(L) + '\n')
    # --- справка по вопросам: позиции
    jp = A + '2. Судебная практика/Судебная практика по вопросам.md'; t = open(jp, encoding='utf-8').read()
    for n in new:
        for sec, suf, txt in n['pos']:
            m = re.search(r'^### %s\. .*?\n\n\|.*?\n\|[-|]+\n((?:\|.*\n)+)' % re.escape(sec), t, re.M)
            t = t[:m.end(1)] + '| %s | %s |\n' % (n['short'] + (', ' + suf if suf else ''), txt) + t[m.end(1):]
    open(jp, 'w', encoding='utf-8').write(t)
